package com.andye.warmod.block;import net.minecraft.core.BlockPos;import net.minecraft.core.Direction;import net.minecraft.util.StringRepresentable;public enum RadarStationPart implements StringRepresentable {BOTTOM_NW(-1,0,-1),BOTTOM_N(0,0,-1),BOTTOM_NE(1,0,-1),BOTTOM_W(-1,0,0),BOTTOM_CENTER(0,0,0),BOTTOM_E(1,0,0),BOTTOM_SW(-1,0,1),BOTTOM_S(0,0,1),BOTTOM_SE(1,0,1),MIDDLE_NW(-1,1,-1),MIDDLE_N(0,1,-1),MIDDLE_NE(1,1,-1),MIDDLE_W(-1,1,0),MIDDLE_CENTER(0,1,0),MIDDLE_E(1,1,0),MIDDLE_SW(-1,1,1),MIDDLE_S(0,1,1),MIDDLE_SE(1,1,1),TOP_NW(-1,2,-1),TOP_N(0,2,-1),TOP_NE(1,2,-1),TOP_W(-1,2,0),TOP_CENTER(0,2,0),TOP_E(1,2,0),TOP_SW(-1,2,1),TOP_S(0,2,1),TOP_SE(1,2,1);private final int x,y,z;RadarStationPart(int x,int y,int z){this.x=x;this.y=y;this.z=z;}public BlockPos offset(Direction facing){return switch(facing){case SOUTH->new BlockPos(-x,y,-z);case EAST->new BlockPos(-z,y,x);case WEST->new BlockPos(z,y,-x);default->new BlockPos(x,y,z);};}public BlockPos resolveCentre(BlockPos pos,Direction facing){BlockPos o=offset(facing);return pos.offset(-o.getX(),-o.getY(),-o.getZ());}public boolean centre(){return this==BOTTOM_CENTER;}public int layer(){return y;}public boolean corner(){return x!=0&&z!=0;}@Override public String getSerializedName(){return name().toLowerCase(java.util.Locale.ROOT);}}